/* Deploy StoredProcedure SJob.ActivityCreateInvoiceRequest using CanonicalAlter from C:\Users\stephen.brett\source\CymBuild.Monorepo\Database\CymBuild_DB\Schema\Programmability\Procedures\SJob.ActivityCreateInvoiceRequest.sql */
/*
    CymBuild generated canonical schema source.
    Generated by       : CYB-361 R7C4 selected DEV schema source sync
    Object             : StoredProcedure SJob.ActivityCreateInvoiceRequest
    Source schema hash : CBAD764B47FD52C9550D68090DD98143B45728AD3B29544B7C5CDABB0BBDCC6A
    Definition SHA-256 : E68CEF63314710917577CEC9F6DF31DFF2403C4D470C5A210406B889BF8D47F1

    This deterministic file was synchronized from an explicitly selected, validated and accepted
    CymBuild_Dev source-definition snapshot. Review and commit the source-control diff before using
    it for promotion.
*/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE OR ALTER PROCEDURE [SJob].[ActivityCreateInvoiceRequest]
	(
		@Guid UNIQUEIDENTIFIER
	)
AS
	BEGIN
		SET NOCOUNT ON

		DECLARE	@MilestoneGuid UNIQUEIDENTIFIER,
				@JobGuid UNIQUEIDENTIFIER,
				@CreatedByUserGuid UNIQUEIDENTIFIER,
				@InvoiceRequestGuid UNIQUEIDENTIFIER = NEWID(),
				@InvoiceRequestItemGuid UNIQUEIDENTIFIER = NEWID(),
				@Net DECIMAL(19,2),
				@FinanceAccountGuid UNIQUEIDENTIFIER,
				@ActivityId INT

		-- CYB-548: WITH (UPDLOCK, HOLDLOCK) takes an update lock on this Activity's row
		-- and holds it for the rest of the caller's transaction. A second call for the
		-- SAME Activity (double-click, or a stalled retry the user repeats) blocks here
		-- until the first call's transaction commits or rolls back, then correctly sees
		-- whatever the first call inserted below - instead of both calls' plain EXISTS
		-- checks passing concurrently under READ COMMITTED and both inserting.
		SELECT	@ActivityId = a.ID
		FROM	SJob.Activities a WITH (UPDLOCK, HOLDLOCK)
		WHERE	(a.Guid = @Guid)

		IF (
			(EXISTS
				(
					SELECT	1
					FROM	SFin.InvoiceRequestItems iri
					WHERE	(iri.ActivityId = @ActivityId)
						AND	(iri.RowStatus NOT IN (0, 254))
				)
			)
			OR (EXISTS
				(
					SELECT	1
					FROM	SFin.TransactionDetails td
					WHERE	(td.ActivityId = @ActivityId)
						AND	(td.RowStatus NOT IN (0, 254))
				)
			)
		)
		BEGIN
			;THROW 60000, N'This Activity has previously been invoiced or an invoice request has already been made.', 1
		END

		IF (
				(NOT EXISTS
					(
						SELECT	1
						FROM	SJob.Activities a
						JOIN	SJob.ActivityStatus ast ON (ast.ID = a.ActivityStatusID)
						WHERE	(ast.IsCompleteStatus = 1)
							AND	(a.Guid = @Guid)
					)
				)
			)
		BEGIN
			;THROW 60000, N'The Activity must be complete before it can be invoiced.', 1
		END

		-- Get the current user.
		SELECT	@CreatedByUserGuid = SCore.GetCurrentUserGuid()

		-- Get the details to create the invoice.
		SELECT	@JobGuid = j.Guid,
				@MilestoneGuid = m.Guid,
				@Net = CASE WHEN a.InvoicingValue > 0 THEN a.InvoicingValue ELSE (i.BillableRate * a.InvoicingQuantity) END,
				@FinanceAccountGuid = fa.Guid
		FROM	SJob.Activities a
		JOIN	SJob.Jobs j ON (j.ID = a.JobId)
		JOIN	SCore.Identities i ON (i.ID = j.SurveyorID)
		JOIN	SCrm.Accounts fa ON (fa.ID = j.FinanceAccountID)
		JOIN	SJob.Milestones m ON (m.id = a.MilestoneID)
		WHERE	(a.Guid = @Guid)

		EXEC SFin.InvoiceRequestUpsert @JobGuid = @JobGuid,				-- uniqueidentifier
									   @RequesterUserGuid = @CreatedByUserGuid,	-- uniqueidentifier
									   @Notes = N'',				-- nvarchar(max)
									   @Guid = @InvoiceRequestGuid,					-- uniqueidentifier
									   @InvoicingType = N'',
									   @ExpectedDate = NULL,
									   @ManualStatus = 0,
									   @PaymentStatusGuid = '00000000-0000-0000-0000-000000000000',
									   @FinanceAccountGuid  = @FinanceAccountGuid

		EXEC sFin.InvoiceRequestItemsUpsert @InvoiceRequestGuid = @InvoiceRequestGuid, -- uniqueidentifier
											@MilestoneGuid = @MilestoneGuid,		-- uniqueidentifier
											@ActivityGuid = @Guid,		-- uniqueidentifier
											@Net = @Net,				-- decimal(19, 2)
											@Guid = @InvoiceRequestItemGuid,				-- uniqueidentifier
											@ShortDescription = N'',
											@RIBAStageGuid = '00000000-0000-0000-0000-000000000000'

	END;
GO

