        @GD_RowStatus,
        @GD_Code,
        @GD_TabName,
        @GD_ShowAsTiles,
        @GD_PageUri,
        @GD_SourceLanguageLabelID,
        @GD_OverrideTargetGuid,
        @GD_ColumnSourceSelectionJson;
END;

CLOSE GridDefinitions_Cursor;
