        INNER JOIN @WorkflowGuidRemap AS m
            ON m.SourceWorkflowGuid = wsng.WorkflowGuid
        WHERE wsng.RunGuid = @RunGuid;

        UPDATE wt
           SET wt.WorkflowGuid = m.TargetWorkflowGuid
        FROM SMigration.Onboarding_WorkflowTransitions AS wt
        INNER JOIN @WorkflowGuidRemap AS m
