    Object             : StoredProcedure SMigration.OnboardingLookup_Runs
    Source schema hash : 2748B6B9E3F9F22E817F463DB089A4D1D6836DB422084DBB6AF980DD22283DC7
    Definition SHA-256 : 5608E6B454B7D47ECB2F26793CD8A4D492153A69FF642062A3913ED1BE1B94BD

    This deterministic file was synchronized from an explicitly selected, validated and accepted
    CymBuild_Dev source-definition snapshot. Review and commit the source-control diff before using
    it for promotion.
*/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE OR ALTER PROCEDURE [SMigration].[OnboardingLookup_Runs]
    @SourceDatabase SYSNAME = NULL
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        Guid = CAST(r.RunGuid AS NVARCHAR(36)),
        Name = CONCAT(CONVERT(NVARCHAR(19), r.CreatedUtc, 120), N' - ', r.SourceDatabase),
        Code = ISNULL(r.SourceDatabase, N''),
        Description = CONCAT(
            CONVERT(NVARCHAR(19), r.CreatedUtc, 120),
            N' | ',
            ISNULL(NULLIF(r.SourceServerName, N''), N'(current server)'),
            N' / ',
            r.SourceDatabase,
            N' -> ',
            ISNULL(NULLIF(r.TargetServerName, N''), N'(current server)'),
            N' / ',
            ISNULL(NULLIF(r.TargetDatabaseName, N''), DB_NAME()),
            N' | ',
            ISNULL(r.Notes, N'')
        )
    FROM SMigration.Onboarding_Run AS r
    WHERE r.RowStatus NOT IN (0,254)
      AND (@SourceDatabase IS NULL OR @SourceDatabase = N'' OR r.SourceDatabase = @SourceDatabase)
    ORDER BY r.CreatedUtc DESC;
END
