AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF @RunGuid IS NULL
        THROW 62230, 'RunGuid is required to apply OnBoarding entity selections to staged data.', 1;

    EXEC SMigration.OnboardingRunEntitySelection_Default @RunGuid = @RunGuid;

