/* Deploy StoredProcedure SMigration.OnboardingRunEntitySelection_List using CanonicalAlter from C:\Users\stephen.brett\source\CymBuild.Monorepo\Database\CymBuild_DB\Schema\Programmability\Procedures\SMigration.OnboardingRunEntitySelection_List.sql */
/*
    CymBuild generated canonical schema source.
    Generated by       : CYB-361 R7C4 selected DEV schema source sync
    Object             : StoredProcedure SMigration.OnboardingRunEntitySelection_List
    Source schema hash : 8335647970708371999106AF2597064DC6533437707F1C83C656EB6E12B03B28
    Definition SHA-256 : F649E803DADA39CB4D13D969A55C7147B39A8E22D118F4FE57AC5CF259C0BCF5

    This deterministic file was synchronized from an explicitly selected, validated and accepted
    CymBuild_Dev source-definition snapshot. Review and commit the source-control diff before using
    it for promotion.
*/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE OR ALTER PROCEDURE [SMigration].[OnboardingRunEntitySelection_List]
(
    @RunGuid UNIQUEIDENTIFIER
)
AS
BEGIN
    SET NOCOUNT ON;

    IF @RunGuid IS NULL
        THROW 62210, 'RunGuid is required to list OnBoarding entity selections.', 1;

    EXEC SMigration.OnboardingEntityScope_Seed;

    SELECT
        es.Guid AS EntityScopeGuid,
        es.Code AS EntityCode,
        es.Name AS EntityName,
        es.Description,
        es.StageTableName,
        es.DisplayOrder,
        CONVERT(BIT, ISNULL(sel.IsSelected, es.DefaultSelected)) AS IsSelected,
        es.DefaultSelected,
        es.CanDeselect,
        es.IsRequired,
        es.RequiredDependencyCodes,
        sel.Guid AS SelectionGuid,
        ISNULL(sel.SelectionSource, N'Default') AS SelectionSource,
        ISNULL(CONVERT(NVARCHAR(30), sel.SelectedOnUtc, 126), N'') AS SelectedOnUtc,
        es.Category,
        es.ScopeType,
        es.IsImplemented,
        es.IsSupportData,
        es.HandlerKey,
        es.PrimaryEntityTypeGuid,
        es.SourceSchemaName,
        es.SourceTableName
    FROM SMigration.Onboarding_EntityScope AS es
    LEFT JOIN SMigration.Onboarding_RunEntitySelections AS sel
        ON sel.RunGuid = @RunGuid
       AND sel.EntityCode = es.Code
       AND sel.RowStatus NOT IN (0,254)
    WHERE es.RowStatus NOT IN (0,254)
      AND es.IsSupportData = 0
    ORDER BY
        CASE es.Category
            WHEN N'Access Foundation' THEN 10
            WHEN N'Operational Configuration' THEN 20
            WHEN N'Additional Eligible Record Types' THEN 30
            WHEN N'Internal / Support Data' THEN 90
            ELSE 80
        END,
        es.DisplayOrder,
        es.Code;
END;
GO

