/* Deploy Trigger SCrm.tr_Accounts_CreditHold_InvoiceModeSync using CanonicalAlter from C:\Users\stephen.brett\source\CymBuild.Monorepo\Database\CymBuild_DB\Schema\Programmability\Triggers\SCrm.tr_Accounts_CreditHold_InvoiceModeSync.sql */
/*
    CymBuild generated canonical schema source.
    Generated by       : CYB-361 R7C4 selected DEV schema source sync
    Object             : Trigger SCrm.tr_Accounts_CreditHold_InvoiceModeSync
    Source schema hash : 538BB4ED92ACF217B92CCEBC3CD3E754BFE2513D9401A61885719F9566DA8F17
    Definition SHA-256 : 54262DEA257B3113F0C41F88984B38B3B30674E15637D657731AC1968DF1E99D

    This deterministic file was synchronized from an explicitly selected, validated and accepted
    CymBuild_Dev source-definition snapshot. Review and commit the source-control diff before using
    it for promotion.
*/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE OR ALTER TRIGGER [SCrm].[tr_Accounts_CreditHold_InvoiceModeSync]
ON [SCrm].[Accounts]
AFTER UPDATE
AS
BEGIN
    SET NOCOUNT ON;

    IF NOT UPDATE(AccountStatusID)
        RETURN;

    -------------------------------------------------------------------------
    -- Build two sets:
    --  - accounts that changed from NOT HOLD -> HOLD
    --  - accounts that changed from HOLD -> NOT HOLD
    -------------------------------------------------------------------------
    DECLARE @ToHold TABLE (AccountId INT NOT NULL PRIMARY KEY);
    DECLARE @ToRelease TABLE (AccountId INT NOT NULL PRIMARY KEY);

    INSERT INTO @ToHold (AccountId)
    SELECT i.ID
    FROM inserted i
    JOIN deleted d ON d.ID = i.ID
    JOIN SCrm.AccountStatus stNew ON stNew.ID = i.AccountStatusID
    JOIN SCrm.AccountStatus stOld ON stOld.ID = d.AccountStatusID
    WHERE ISNULL(stOld.IsHold, 0) = 0
      AND ISNULL(stNew.IsHold, 0) = 1;

    INSERT INTO @ToRelease (AccountId)
    SELECT i.ID
    FROM inserted i
    JOIN deleted d ON d.ID = i.ID
    JOIN SCrm.AccountStatus stNew ON stNew.ID = i.AccountStatusID
    JOIN SCrm.AccountStatus stOld ON stOld.ID = d.AccountStatusID
    WHERE ISNULL(stOld.IsHold, 0) = 1
      AND ISNULL(stNew.IsHold, 0) = 0;

    -------------------------------------------------------------------------
    -- Apply hold -> Pause jobs
    -------------------------------------------------------------------------
    DECLARE @A INT;

    DECLARE cHold CURSOR LOCAL FAST_FORWARD FOR
        SELECT AccountId FROM @ToHold;

    OPEN cHold;
    FETCH NEXT FROM cHold INTO @A;

    WHILE @@FETCH_STATUS = 0
    BEGIN
        EXEC SFin.JobInvoiceProcessingMode_ApplyCreditHoldPause
            @FinanceAccountId = @A;

        FETCH NEXT FROM cHold INTO @A;
    END

    CLOSE cHold;
    DEALLOCATE cHold;

    -------------------------------------------------------------------------
    -- Apply release -> set jobs to Manual (only those paused-by-hold)
    -------------------------------------------------------------------------
    DECLARE cRelease CURSOR LOCAL FAST_FORWARD FOR
        SELECT AccountId FROM @ToRelease;

    OPEN cRelease;
    FETCH NEXT FROM cRelease INTO @A;

    WHILE @@FETCH_STATUS = 0
    BEGIN
        EXEC SFin.JobInvoiceProcessingMode_ClearCreditHoldToManual
            @FinanceAccountId = @A;

        FETCH NEXT FROM cRelease INTO @A;
    END

    CLOSE cRelease;
    DEALLOCATE cRelease;
END
GO

